<?php
if (!function_exists('email_marketing_setting')) { function email_marketing_setting($name, $default = '') { static $cache = []; if (array_key_exists($name,$cache)) return $cache[$name]; $row = db_connect('default')->table(get_db_prefix().'email_marketing_settings')->where('setting_name',$name)->get()->getRow(); return $cache[$name] = $row ? $row->setting_value : $default; } }
if (!function_exists('email_marketing_unsubscribe_url')) { function email_marketing_unsubscribe_url($email) { return site_url('email_unsubscribe/' . rtrim(strtr(base64_encode(hash_hmac('sha256', strtolower(trim($email)), encryption_key(), true) . '|' . strtolower(trim($email))), '+/', '-_'), '=')); } }
if (!function_exists('email_marketing_mail_configured')) { function email_marketing_mail_configured() { $protocol=(string)get_setting('email_protocol'); if ($protocol==='smtp') return (bool)get_setting('email_smtp_host') && (bool)get_setting('email_smtp_port') && (bool)get_setting('email_smtp_user') && (bool)get_setting('email_smtp_pass') && (bool)get_setting('email_sent_from_address'); if ($protocol==='microsoft_outlook') return (bool)get_setting('outlook_smtp_authorized') && (bool)get_setting('email_sent_from_address'); return false; } }
if (!function_exists('email_marketing_approved_test_emails_from')) { function email_marketing_approved_test_emails_from($raw) { $emails=[];foreach(preg_split('/[\s,;]+/', (string)$raw, -1, PREG_SPLIT_NO_EMPTY) as $email){$email=filter_var(strtolower(trim($email)),FILTER_VALIDATE_EMAIL);if($email)$emails[$email]=true;}return array_keys($emails); } }
if (!function_exists('email_marketing_approved_test_emails')) { function email_marketing_approved_test_emails() { return email_marketing_approved_test_emails_from(email_marketing_setting('approved_test_emails','')); } }
